import java.io.*;
import java.util.*;

class Book {
    String title;
    String author;
    String bookID;
    boolean borrowed;

    public Book(String title, String author, String bookID) {
        this.title = title;
        this.author = author;
        this.bookID = bookID;
        this.borrowed = false;
    }
}

class Library {
    List<Book> books;

    public Library() {
        books = new ArrayList<>();
    }

    public boolean addBook(String title, String author, String bookID) {
        for (Book book : books) {
            if (book.bookID.equals(bookID)) {
                return false;
            }
        }
        books.add(new Book(title, author, bookID));
        return true;
    }

    public boolean borrowBook(String bookID) {
        for (Book book : books) {
            if (book.bookID.equals(bookID)) {
                if (book.borrowed) {
                    return false;
                }
                book.borrowed = true;
                return true;
            }
        }
        return false;
    }

    public boolean returnBook(String bookID) {
        for (Book book : books) {
            if (book.bookID.equals(bookID)) {
                if (!book.borrowed) {
                    return false;
                }
                book.borrowed = false;
                return true;
            }
        }
        return false;
    }
}

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        Library library = new Library();
        String line;

        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }

            String[] tokens = parseLine(line);
            if (tokens.length == 0) {
                continue;
            }

            String command = tokens[0];

            if (command.equals("add")) {
                if (tokens.length >= 4) {
                    String title = tokens[1];
                    String author = tokens[2];
                    String bookID = tokens[3];

                    if (library.addBook(title, author, bookID)) {
                        System.out.println("Book added successfully.");
                    } else {
                        System.out.println("Error: Book with ID " + bookID + " already exists.");
                    }
                } else {
                    System.out.println("Error: Invalid add command.");
                }
            } else if (command.equals("borrow")) {
                if (tokens.length >= 2) {
                    String bookID = tokens[1];

                    if (library.borrowBook(bookID)) {
                        System.out.println("Book borrowed successfully.");
                    } else {
                        System.out.println("Error: Cannot borrow book with ID " + bookID + ".");
                    }
                } else {
                    System.out.println("Error: Invalid borrow command.");
                }
            } else if (command.equals("return")) {
                if (tokens.length >= 2) {
                    String bookID = tokens[1];

                    if (library.returnBook(bookID)) {
                        System.out.println("Book returned successfully.");
                    } else {
                        System.out.println("Error: Cannot return book with ID " + bookID + ".");
                    }
                } else {
                    System.out.println("Error: Invalid return command.");
                }
            } else {
                System.out.println("Error: Unknown command.");
            }
        }
    }

    private static String[] parseLine(String line) {
        List<String> tokens = new ArrayList<>();
        StringBuilder current = new StringBuilder();
        boolean inQuotes = false;

        for (int i = 0; i < line.length(); i++) {
            char c = line.charAt(i);

            if (c == '"') {
                if (inQuotes) {
                    tokens.add(current.toString());
                    current = new StringBuilder();
                }
                inQuotes = !inQuotes;
            } else if (c == ' ' && !inQuotes) {
                if (current.length() > 0) {
                    tokens.add(current.toString());
                    current = new StringBuilder();
                }
            } else {
                current.append(c);
            }
        }

        if (current.length() > 0) {
            tokens.add(current.toString());
        }

        return tokens.toArray(new String[0]);
    }
}
